import { defineConfig } from "vitest/config";
export default defineConfig({
  test: {
    environment: "node",
    include: ["tests/**/*.test.ts"],
    // Rebuild better-sqlite3 before tests — prevents binary drift after nvm switches.
    globalSetup: ["./tests/setup/rebuild-sqlite.ts"],
    // Serialize test files to eliminate SQLite write contention.
    // pool:"forks" + maxWorkers:1 replaces the removed poolOptions.forks.singleFork (Vitest 4).
    pool: "forks",
    maxWorkers: 1,
    // Cold fork load of better-sqlite3 native module can exceed 5s default.
    testTimeout: 15000,
  },
});

/**
 * Recipe Commerce MCP — Eval Scorers
 *
 * Four scoring dimensions:
 *   ingredient_recall — did extraction find the expected ingredients? (recall + required gate)
 *   value             — are product matches actionable? (affiliate data, commissions present)
 *   accuracy          — precision/recall/F1 against ground truth ingredients
 *   cost              — was token count within budget?
 */

import type { ScorerResult, RecipeEvalCase, RecipeExtractionBundle } from "./eval-types.js";

// ---------------------------------------------------------------------------
// Ingredient recall scorer
// ---------------------------------------------------------------------------

export function scoreIngredientRecall(
  evalCase: RecipeEvalCase,
  bundle: RecipeExtractionBundle
): ScorerResult {
  const expected = evalCase.expectedIngredients;
  const actual = bundle.ingredients ?? [];

  if (expected.length === 0) {
    return {
      dimension: "ingredient_recall",
      score: 100,
      target: 80,
      details: "No ingredients expected — skipped",
      passed: true,
    };
  }

  const required = expected.filter((e) => e.required);
  let foundRequired = 0;
  let foundTotal = 0;

  for (const exp of expected) {
    const hit = actual.some((a) =>
      a.name.toLowerCase().includes(exp.name.toLowerCase()) ||
      exp.name.toLowerCase().includes(a.name.toLowerCase())
    );
    if (hit) {
      foundTotal++;
      if (exp.required) foundRequired++;
    }
  }

  const requiredRecall = required.length > 0 ? (foundRequired / required.length) * 100 : 100;
  const overallRecall = (foundTotal / expected.length) * 100;
  const score = Math.round(requiredRecall * 0.7 + overallRecall * 0.3);

  return {
    dimension: "ingredient_recall",
    score,
    target: 80,
    details: `${foundTotal}/${expected.length} found (${foundRequired}/${required.length} required). Actual total: ${actual.length}`,
    passed: score >= 80,
  };
}

// ---------------------------------------------------------------------------
// Value scorer — are product matches actionable?
// ---------------------------------------------------------------------------

export function scoreValue(
  evalCase: RecipeEvalCase,
  bundle: RecipeExtractionBundle
): ScorerResult {
  const products = bundle.products ?? [];
  let score = 0;
  const reasons: string[] = [];

  // Has product matches (40pts)
  if (products.length > 0) {
    score += 40;
    reasons.push(`${products.length} products matched`);
  }

  // Has commission rates (30pts)
  const hasCommission = products.some((p) => p.commissionRate > 0);
  if (hasCommission) {
    score += 30;
    const avgCommission = products.reduce((s, p) => s + p.commissionRate, 0) / products.length;
    reasons.push(`avg commission: ${(avgCommission * 100).toFixed(1)}%`);
  }

  // Has affiliate program assignments (30pts)
  const hasAffiliateProgram = products.some((p) => p.affiliateProgram && p.affiliateProgram !== "other");
  if (hasAffiliateProgram) { score += 30; reasons.push("affiliate programs assigned"); }

  return {
    dimension: "value",
    score,
    target: 70,
    details: reasons.join(", ") || "No product matches found",
    passed: score >= 70,
  };
}

// ---------------------------------------------------------------------------
// Accuracy scorer — F1 against ground truth ingredients
// ---------------------------------------------------------------------------

export function scoreAccuracy(
  evalCase: RecipeEvalCase,
  bundle: RecipeExtractionBundle
): ScorerResult {
  const expected = evalCase.expectedIngredients;
  const actual = bundle.ingredients ?? [];

  if (expected.length === 0 && actual.length === 0) {
    return { dimension: "accuracy", score: 100, target: 80, details: "Empty case (correct)", passed: true };
  }

  let truePositives = 0;
  for (const exp of expected) {
    if (actual.some((a) =>
      a.name.toLowerCase().includes(exp.name.toLowerCase()) ||
      exp.name.toLowerCase().includes(a.name.toLowerCase())
    )) {
      truePositives++;
    }
  }

  const precision = actual.length > 0 ? truePositives / actual.length : 0;
  const recall = expected.length > 0 ? truePositives / expected.length : 0;
  const f1 = precision + recall > 0 ? 2 * precision * recall / (precision + recall) : 0;
  const score = Math.round(f1 * 100);

  return {
    dimension: "accuracy",
    score,
    target: 80,
    details: `F1: ${score}/100 — precision: ${Math.round(precision * 100)}%, recall: ${Math.round(recall * 100)}%`,
    passed: score >= 80,
  };
}

// ---------------------------------------------------------------------------
// Cost scorer — within token budget?
// ---------------------------------------------------------------------------

export function scoreCost(
  evalCase: RecipeEvalCase,
  bundle: RecipeExtractionBundle
): ScorerResult {
  const maxTokens = evalCase.maxTokens ?? 2000;
  // Estimate tokens from JSON output size (rough: 4 chars ≈ 1 token)
  const outputStr = JSON.stringify({ ingredients: bundle.ingredients, products: bundle.products });
  const estimatedTokens = Math.ceil(outputStr.length / 4);
  const pct = Math.round((estimatedTokens / maxTokens) * 100);
  const score = Math.max(0, 100 - Math.max(0, pct - 100));

  return {
    dimension: "cost",
    score,
    target: 80,
    details: `~${estimatedTokens} tokens (budget: ${maxTokens}). ${pct <= 100 ? "Within budget" : `${pct - 100}% over budget`}`,
    passed: score >= 80,
  };
}

export const ALL_SCORERS = [scoreIngredientRecall, scoreValue, scoreAccuracy, scoreCost];

/**
 * Input size limit tests (FIND-4).
 *
 * Verifies that the Zod schemas in server.ts enforce the expected upper bounds
 * on all user-supplied fields that reach OpenAI. Each test imports the exported
 * limit constants so the assertions stay in sync with the implementation.
 */

import { describe, it, expect } from "vitest";
import { z } from "zod";
import {
  TRANSCRIPT_MAX_CHARS,
  ID_MAX_CHARS,
  API_KEY_MAX_CHARS,
  RECIPE_NAME_MAX,
  INGREDIENT_NAME_MAX,
  INGREDIENT_QUANTITY_MAX,
} from "../src/server.js";

// ============================================================================
// transcript (extract_recipe_ingredients)
// ============================================================================

describe("transcript field limits", () => {
  const schema = z.string().min(1).max(TRANSCRIPT_MAX_CHARS);

  it("accepts a transcript at the exact max length", () => {
    expect(schema.safeParse("x".repeat(TRANSCRIPT_MAX_CHARS)).success).toBe(true);
  });

  it("rejects a transcript one character over the limit", () => {
    const result = schema.safeParse("x".repeat(TRANSCRIPT_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });

  it("rejects an empty transcript", () => {
    expect(schema.safeParse("").success).toBe(false);
  });
});

// ============================================================================
// recipe_id / id fields
// ============================================================================

describe("ID field limits", () => {
  const schema = z.string().max(ID_MAX_CHARS).optional();

  it("accepts an ID at the exact max length", () => {
    expect(schema.safeParse("a".repeat(ID_MAX_CHARS)).success).toBe(true);
  });

  it("rejects an ID one character over the limit", () => {
    const result = schema.safeParse("a".repeat(ID_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });

  it("accepts undefined (optional)", () => {
    expect(schema.safeParse(undefined).success).toBe(true);
  });
});

// ============================================================================
// api_key field
// ============================================================================

describe("api_key field limits", () => {
  const schema = z.string().max(API_KEY_MAX_CHARS).optional();

  it("accepts an api_key at the exact max length", () => {
    expect(schema.safeParse("k".repeat(API_KEY_MAX_CHARS)).success).toBe(true);
  });

  it("rejects an api_key one character over the limit", () => {
    const result = schema.safeParse("k".repeat(API_KEY_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });
});

// ============================================================================
// recipe_name field (suggest_affiliate_products)
// ============================================================================

describe("recipe_name field limits", () => {
  const schema = z.string().min(1).max(RECIPE_NAME_MAX);

  it("accepts a recipe name at the exact max length", () => {
    expect(schema.safeParse("r".repeat(RECIPE_NAME_MAX)).success).toBe(true);
  });

  it("rejects a recipe name one character over the limit", () => {
    expect(schema.safeParse("r".repeat(RECIPE_NAME_MAX + 1)).success).toBe(false);
  });
});

// ============================================================================
// ingredient name field (match_ingredients_to_products, suggest_affiliate_products)
// ============================================================================

describe("ingredient name field limits", () => {
  const schema = z.string().min(1).max(INGREDIENT_NAME_MAX);

  it("accepts an ingredient name at the exact max length", () => {
    expect(schema.safeParse("i".repeat(INGREDIENT_NAME_MAX)).success).toBe(true);
  });

  it("rejects an ingredient name one character over the limit", () => {
    expect(schema.safeParse("i".repeat(INGREDIENT_NAME_MAX + 1)).success).toBe(false);
  });
});

// ============================================================================
// ingredient quantity field
// ============================================================================

describe("ingredient quantity field limits", () => {
  const schema = z.string().max(INGREDIENT_QUANTITY_MAX).optional();

  it("accepts a quantity at the exact max length", () => {
    expect(schema.safeParse("1".repeat(INGREDIENT_QUANTITY_MAX)).success).toBe(true);
  });

  it("rejects a quantity one character over the limit", () => {
    expect(schema.safeParse("1".repeat(INGREDIENT_QUANTITY_MAX + 1)).success).toBe(false);
  });

  it("accepts undefined (optional)", () => {
    expect(schema.safeParse(undefined).success).toBe(true);
  });
});

/**
 * Recipe Commerce MCP — Eval Framework Types
 *
 * Quality evaluation for ingredient extraction accuracy on real-world recipe content.
 * Three modes:
 *   fixture  — mocked extractor, tests scoring logic and schema correctness
 *   live     — real OpenAI calls, validates extraction quality on real content
 *   snapshot — update golden snapshots from live output
 */

import type { Ingredient, ProductMatch } from "../src/types.js";

// ============================================================================
// EVAL CASE
// ============================================================================

export interface ExpectedIngredient {
  /** Exact or partial ingredient name match (case-insensitive) */
  name: string;
  /** Expected category */
  category: string;
  /** Must be present in output — failure if missing */
  required: boolean;
}

export interface RecipeEvalCase {
  id: string;
  name: string;
  /** Data provenance — where the recipe content was sourced from */
  source: string;
  /** Full recipe transcript or description (real content from source) */
  content: string;
  /** Expected recipe name (partial match) */
  expectedRecipeName?: string;
  /** Ingredients we expect extraction to identify */
  expectedIngredients: ExpectedIngredient[];
  /** Max token budget for JSON output (default: 2000) */
  maxTokens?: number;
}

// ============================================================================
// EVAL RESULT
// ============================================================================

export interface ScorerResult {
  dimension: string;
  score: number;   // 0-100
  target: number;  // pass threshold
  details: string;
  passed: boolean;
}

export interface RecipeExtractionBundle {
  recipeName: string;
  ingredients: Ingredient[];
  products: ProductMatch[];
  ai_cost_usd: number;
}

export interface EvalResult {
  caseId: string;
  caseName: string;
  timestamp: string;
  scores: ScorerResult[];
  overallScore: number;
  passed: boolean;
  ingredientsExtracted: Ingredient[];
  productsMatched: ProductMatch[];
}

/**
 * Recipe Commerce MCP — Eval Runner
 *
 * Usage:
 *   npx tsx tests/eval-runner.ts               # fixture mode (mocked extractor)
 *   EVAL_LIVE=true npx tsx tests/eval-runner.ts # live mode (real OpenAI API)
 *
 * Fixture mode: injects a deterministic mock that returns all expectedIngredients.
 * Live mode: calls extractRecipeIngredients() + computeProductMatches() with real API.
 */

import type { RecipeEvalCase, EvalResult, RecipeExtractionBundle } from "./eval-types.js";
import { ALL_SCORERS } from "./eval-scorers.js";
import { ALL_CASES } from "./eval-cases/index.js";
import type { Ingredient } from "../src/types.js";

// ---------------------------------------------------------------------------
// Fixture mock — returns expectedIngredients as Ingredients + mock product matches
// ---------------------------------------------------------------------------

function mockExtraction(evalCase: RecipeEvalCase): RecipeExtractionBundle {
  const ingredients: Ingredient[] = evalCase.expectedIngredients.map((ei) => ({
    name: ei.name,
    category: ei.category as Ingredient["category"],
    optional: false,
  }));

  // Mock product matches — one per ingredient with realistic affiliate data
  const products = ingredients.map((ing) => ({
    ingredient: ing.name,
    productName: `${ing.name} (Mock Product)`,
    brand: "MockBrand",
    category: ing.category,
    affiliateProgram: "amazon_associates" as const,
    estimatedPrice: { min: 5, max: 20, currency: "USD" as const },
    commissionRate: 0.04,
    affiliateScore: 70,
    substitutes: [],
  }));

  return { recipeName: evalCase.name, ingredients, products, ai_cost_usd: 0 };
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

async function runCase(
  evalCase: RecipeEvalCase,
  mode: "fixture" | "live"
): Promise<EvalResult> {
  const start = Date.now();
  let bundle: RecipeExtractionBundle;

  if (mode === "live") {
    const { extractRecipeIngredients, computeProductMatches, setOpenAIClient } =
      await import("../src/extractor.js");
    const OpenAI = (await import("openai")).default;
    const apiKey = process.env.OPENAI_API_KEY;
    if (!apiKey) throw new Error("OPENAI_API_KEY not set for live eval");
    setOpenAIClient(new OpenAI({ apiKey }));
    const extracted = await extractRecipeIngredients({ transcript: evalCase.content });
    const products = computeProductMatches(extracted.result.ingredients);
    bundle = {
      recipeName: extracted.result.recipeName,
      ingredients: extracted.result.ingredients,
      products,
      ai_cost_usd: extracted.ai_cost_usd,
    };
  } else {
    bundle = mockExtraction(evalCase);
  }

  const elapsedMs = Date.now() - start;
  void elapsedMs; // available for future timing scorer

  const scores = ALL_SCORERS.map((scorer) => scorer(evalCase, bundle));
  const overallScore = Math.round(scores.reduce((s, r) => s + r.score, 0) / scores.length);

  return {
    caseId: evalCase.id,
    caseName: evalCase.name,
    timestamp: new Date().toISOString(),
    scores,
    overallScore,
    passed: scores.every((s) => s.passed),
    ingredientsExtracted: bundle.ingredients,
    productsMatched: bundle.products,
  };
}

async function main() {
  const mode = process.env.EVAL_LIVE === "true" ? "live" : "fixture";
  console.log(`\n🧪 Recipe Commerce MCP — Eval (mode: ${mode})\n`);

  const results: EvalResult[] = [];
  for (const evalCase of ALL_CASES) {
    process.stdout.write(`  ${evalCase.name}... `);
    try {
      const result = await runCase(evalCase, mode);
      results.push(result);
      const status = result.passed ? "✅ PASS" : "❌ FAIL";
      console.log(`${status} (${result.overallScore}/100)`);
      for (const score of result.scores) {
        const icon = score.passed ? "  ✓" : "  ✗";
        console.log(`${icon} ${score.dimension}: ${score.score}/${score.target} — ${score.details}`);
      }
    } catch (err) {
      console.log(`💥 ERROR: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  const passed = results.filter((r) => r.passed).length;
  const total = results.length;
  console.log(`\nResults: ${passed}/${total} cases passed\n`);

  if (passed < total) process.exit(1);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

