/**
 * SQLite cache + usage metering for Recipe Commerce MCP.
 *
 * Two concerns in one file (both lightweight):
 * 1. RecipeCache — stores extraction results keyed by recipe_id
 * 2. UsageTracker — tracks daily free-tier calls per agent, records usage events
 */

import Database from "better-sqlite3";
import { existsSync, mkdirSync } from "node:fs";
import { resolve } from "node:path";
import type { ExtractionResult } from "./types.js";

// ============================================================================
// CONSTANTS
// ============================================================================

const DEFAULT_DB_PATH = "./data/cache.db";
/** Free tier calls per day per agent (no auth required). */
const FREE_TIER_DAILY_LIMIT = 200;

// ============================================================================
// CACHE
// ============================================================================

export class RecipeCache {
  private readonly db: Database.Database;

  // Prepared statements
  private readonly stmtGet: Database.Statement;
  private readonly stmtSet: Database.Statement;
  private readonly stmtGetDailyCount: Database.Statement;
  private readonly stmtRecordUsage: Database.Statement;

  constructor(dbPath?: string) {
    const rawPath = dbPath ?? process.env["CACHE_DIR"] ?? DEFAULT_DB_PATH;
    const resolvedPath = rawPath === ":memory:" ? ":memory:" : resolve(rawPath);

    // Ensure directory exists (skip for in-memory db)
    if (resolvedPath !== ":memory:") {
      const dir = resolvedPath.substring(0, resolvedPath.lastIndexOf("/"));
      if (dir && !existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }
    }

    this.db = new Database(resolvedPath);
    this.db.pragma("journal_mode = WAL");
    this.db.pragma("synchronous = NORMAL");

    this.initSchema();

    this.stmtGet = this.db.prepare(
      `SELECT data FROM recipe_cache WHERE recipe_id = ?`
    );

    this.stmtSet = this.db.prepare(
      `INSERT OR REPLACE INTO recipe_cache (recipe_id, data, created_at)
       VALUES (?, ?, ?)`
    );

    this.stmtGetDailyCount = this.db.prepare(
      `SELECT COUNT(*) as count FROM usage_events
       WHERE agent_id = ? AND DATE(timestamp, 'unixepoch') = DATE('now')`
    );

    this.stmtRecordUsage = this.db.prepare(
      `INSERT INTO usage_events (agent_id, tool_name, timestamp, payment_method, amount_usd, success)
       VALUES (?, ?, ?, ?, ?, ?)`
    );
  }

  // --------------------------------------------------------------------------
  // Extraction cache
  // --------------------------------------------------------------------------

  get(recipeId: string): ExtractionResult | null {
    const row = this.stmtGet.get(recipeId) as { data: string } | undefined;
    if (!row) return null;
    try {
      return JSON.parse(row.data) as ExtractionResult;
    } catch {
      return null;
    }
  }

  set(recipeId: string, result: ExtractionResult): void {
    const now = Math.floor(Date.now() / 1000);
    this.stmtSet.run(recipeId, JSON.stringify(result), now);
  }

  // --------------------------------------------------------------------------
  // Free tier metering
  // --------------------------------------------------------------------------

  /**
   * Check if agent is within free tier limit.
   * Returns true if the call is allowed.
   */
  checkFreeTier(agentId: string): boolean {
    const row = this.stmtGetDailyCount.get(agentId) as { count: number };
    return row.count < FREE_TIER_DAILY_LIMIT;
  }

  /**
   * Get the number of free calls used today by this agent.
   */
  getFreeTierUsed(agentId: string): number {
    const row = this.stmtGetDailyCount.get(agentId) as { count: number };
    return row.count;
  }

  /**
   * Record a tool usage event.
   */
  recordUsage(params: {
    agentId: string;
    toolName: string;
    paymentMethod: string;
    amountUsd: number;
    success: boolean;
  }): void {
    const now = Math.floor(Date.now() / 1000);
    this.stmtRecordUsage.run(
      params.agentId,
      params.toolName,
      now,
      params.paymentMethod,
      params.amountUsd,
      params.success ? 1 : 0
    );
  }

  // --------------------------------------------------------------------------
  // Lifecycle
  // --------------------------------------------------------------------------

  close(): void {
    this.db.close();
  }

  // --------------------------------------------------------------------------
  // Private
  // --------------------------------------------------------------------------

  private initSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS recipe_cache (
        recipe_id  TEXT PRIMARY KEY,
        data       TEXT NOT NULL,
        created_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS usage_events (
        id             INTEGER PRIMARY KEY AUTOINCREMENT,
        agent_id       TEXT NOT NULL,
        tool_name      TEXT NOT NULL,
        timestamp      INTEGER NOT NULL,
        payment_method TEXT,
        amount_usd     REAL DEFAULT 0,
        success        INTEGER DEFAULT 1
      );

      CREATE INDEX IF NOT EXISTS idx_usage_agent_day
        ON usage_events(agent_id, timestamp);
    `);
  }
}

// ============================================================================
// FACTORY
// ============================================================================

let _instance: RecipeCache | null = null;

/**
 * Get the shared cache instance (singleton per process).
 * Pass a custom dbPath on first call to override the default location.
 */
export function getCache(dbPath?: string): RecipeCache {
  if (!_instance) {
    _instance = new RecipeCache(dbPath);
  }
  return _instance;
}

export { FREE_TIER_DAILY_LIMIT };

/**
 * Recipe Commerce MCP — Eval Framework Types
 *
 * Evaluates extractRecipeIngredients() output against ground truth.
 * Focuses on ingredient + equipment extraction quality.
 */

import type { ExtractionResult } from "../../types.js";

export interface RecipeEvalCase {
  id: string;
  name: string;
  description: string;
  /** Raw transcript text (not a URL — deterministic, network-free) */
  transcript: string;
  recipeId?: string;
  /** Expected ingredients — ground truth for recall/precision scoring */
  expectedIngredients: ExpectedIngredient[];
  /** Expected equipment */
  expectedEquipment: ExpectedEquipmentItem[];
  /** Maximum cost in USD */
  maxCostUsd?: number;
}

export interface ExpectedIngredient {
  name: string;
  required: boolean;
  category?: string;
}

export interface ExpectedEquipmentItem {
  name: string;
  required: boolean;
}

export interface ScorerResult {
  dimension: string;
  score: number;       // 0-100
  target: number;      // target score 0-100
  weight: number;      // business weight 0-1
  details: string;
  passed: boolean;
}

export interface EvalResult {
  caseId: string;
  caseName: string;
  timestamp: string;
  mode: "fixture" | "live";
  scores: ScorerResult[];
  overallScore: number;
  passed: boolean;
  durationMs: number;
  /** Captured metrics for value narrative fill-in */
  metrics?: EvalMetrics;
  error?: string;
}

export interface EvalMetrics {
  ingredient_count: number;
  equipment_count: number;
  latency_ms: number;
  cost_usd: number;
  /** Recall of required ingredients (0-1) */
  required_ingredient_recall: number;
  /** Recall of required equipment (0-1) */
  required_equipment_recall: number;
  /** Combined F1 across ingredients */
  f1: number;
}

export interface EvalReport {
  timestamp: string;
  mode: "fixture" | "live";
  results: EvalResult[];
  summary: {
    totalCases: number;
    passed: number;
    failed: number;
    overallScore: number;
    dimensionAverages: Record<string, number>;
  };
  /** Aggregated metrics across all cases (for value narrative fill-in) */
  aggregatedMetrics: {
    avg_entity_count: number;
    avg_latency_ms: number;
    avg_cost_usd: number;
    avg_f1: number;
    avg_ingredient_count: number;
    avg_equipment_count: number;
  };
  priorities: ImprovementPriority[];
}

export interface ImprovementPriority {
  dimension: string;
  gap: number;
  weightedGap: number;
  suggestion: string;
}

export type { ExtractionResult };

#!/usr/bin/env tsx
/**
 * Recipe Commerce MCP — Eval CLI
 *
 * Usage:
 *   cd /home/jonathan/recipe-commerce-mcp
 *   npx tsx src/__tests__/eval/eval-cli.ts              # fixture (synthetic, instant)
 *   EVAL_LIVE=true npx tsx src/__tests__/eval/eval-cli.ts   # live (real OpenAI calls)
 *
 * Live mode output is saved to:
 *   src/__tests__/eval/reports/YYYY-MM-DD-live.json
 *
 * Use the aggregatedMetrics in the report to fill in production/value-narratives.md.
 */

import { writeFileSync, mkdirSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { ALL_RECIPE_EVAL_CASES } from "./cases/index.js";
import { scoreCase, buildReport } from "./runner.js";
import type { EvalResult } from "./types.js";
import type { ExtractionResult } from "../../types.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPORTS_DIR = resolve(__dirname, "reports");

const isLive = process.env["EVAL_LIVE"] === "true";
const mode = isLive ? "live" : "fixture";

async function main() {
  mkdirSync(REPORTS_DIR, { recursive: true });

  console.log(`\n🍳  Recipe Commerce MCP — Eval Suite (${mode} mode)\n`);
  console.log("─".repeat(60));

  const results: EvalResult[] = [];

  for (const evalCase of ALL_RECIPE_EVAL_CASES) {
    console.log(`\n▸ ${evalCase.name}`);

    let extractionResult: ExtractionResult;
    let costUsd: number;
    const startTime = Date.now();

    try {
      if (isLive) {
        const raw = await runLive(evalCase.transcript, evalCase.recipeId);
        extractionResult = raw.result;
        costUsd = raw.ai_cost_usd;
      } else {
        const fixture = buildFixture(evalCase.expectedIngredients.length);
        extractionResult = fixture.result;
        costUsd = fixture.ai_cost_usd;
      }
    } catch (err) {
      const errMsg = err instanceof Error ? err.message : String(err);
      console.error(`  ✗ ERROR: ${errMsg}`);
      results.push({
        caseId: evalCase.id,
        caseName: evalCase.name,
        timestamp: new Date().toISOString(),
        mode,
        scores: [],
        overallScore: 0,
        passed: false,
        durationMs: Date.now() - startTime,
        error: errMsg,
      });
      continue;
    }

    const durationMs = Date.now() - startTime;
    const evalResult = scoreCase(evalCase, extractionResult, costUsd, durationMs);
    evalResult.mode = mode;
    results.push(evalResult);

    const status = evalResult.passed ? "✓ PASS" : "✗ FAIL";
    console.log(`  ${status}  (score: ${evalResult.overallScore}/100, ${durationMs}ms)`);
    for (const s of evalResult.scores) {
      const ind = s.passed ? "✓" : "✗";
      console.log(`    ${ind} ${s.dimension}: ${s.score}/${s.target} — ${s.details}`);
    }
    if (evalResult.metrics) {
      const m = evalResult.metrics;
      console.log(
        `    📊 ingredients=${m.ingredient_count}, equipment=${m.equipment_count}, F1=${(m.f1 * 100).toFixed(0)}%, cost=$${m.cost_usd.toFixed(5)}`,
      );
    }
  }

  const report = buildReport(results, mode);

  // Print summary
  console.log("\n" + "═".repeat(60));
  console.log(`RECIPE EVAL SUMMARY  (${mode} mode)`);
  console.log("═".repeat(60));
  console.log(`Cases: ${report.summary.passed}/${report.summary.totalCases} passed`);
  console.log(`Overall score: ${report.summary.overallScore}/100`);
  console.log("\nDimension averages:");
  for (const [dim, avg] of Object.entries(report.summary.dimensionAverages)) {
    console.log(`  ${dim}: ${avg}/100`);
  }

  const m = report.aggregatedMetrics;
  console.log("\nAggregated metrics (for value-narratives.md fill-in):");
  console.log(`  avg_ingredient_count: ${m.avg_ingredient_count}`);
  console.log(`  avg_equipment_count:  ${m.avg_equipment_count}`);
  console.log(`  avg_latency_ms:       ${m.avg_latency_ms}`);
  console.log(`  avg_cost_usd:         $${m.avg_cost_usd.toFixed(5)}`);
  console.log(`  avg_f1:               ${(m.avg_f1 * 100).toFixed(0)}%`);

  // Revenue estimate (ingredient affiliate formula)
  const revenuePerRecipe = m.avg_ingredient_count * 0.04 * 12;
  console.log(`\n  💰 Revenue estimate: $${revenuePerRecipe.toFixed(2)}/recipe`);
  console.log(`     (${m.avg_ingredient_count} ingredients × 4% commission × $12 avg price)`);

  if (report.priorities.length > 0) {
    console.log("\nImprovement priorities:");
    for (const p of report.priorities.slice(0, 5)) {
      console.log(`  [${p.weightedGap.toFixed(1)}] ${p.dimension}: ${p.suggestion}`);
    }
  }

  // Write report
  const dateStr = new Date().toISOString().slice(0, 10);
  const reportPath = resolve(REPORTS_DIR, `${dateStr}-${mode}.json`);
  writeFileSync(reportPath, JSON.stringify(report, null, 2) + "\n");
  console.log(`\nReport: ${reportPath}`);

  process.exit(report.summary.failed > 0 ? 1 : 0);
}

async function runLive(
  transcript: string,
  recipeId?: string,
): Promise<{ result: ExtractionResult; ai_cost_usd: number }> {
  const { extractRecipeIngredients } = await import("../../extractor.js");

